challenge.starter:
function Counter() {
  const [count, setCount] = useState(0);
  // add + and − buttons; clamp at 0
}

challenge.solution:
function Counter() {
  const [count, setCount] = useState(0);
  return (<div>
    <button onClick={() => setCount(c => Math.max(0, c - 1))}>−</button>
    <span>{count}</span>
    <button onClick={() => setCount(c => c + 1)}>+</button>
  </div>);
}

