challenge.starter:
function AddTaskForm({ onAdd }) {
  const [draft, setDraft] = useState('');
  // on submit: onAdd(draft), then clear
}

challenge.solution:
function AddTaskForm({ onAdd }) {
  const [draft, setDraft] = useState('');
  const submit = () => { const t = draft.trim(); if (t){ onAdd(t); setDraft(''); } };
  return <><input value={draft} onChange={e=>setDraft(e.target.value)} /><button onClick={submit}>Add</button></>;
}

