challenge.starter:
function useTasks(initial = []) {
  // useState + add/toggle/remove; return them
}

challenge.solution:
function useTasks(initial=[]) {
  const [tasks,setTasks]=useState(initial);
  const add=t=>setTasks(p=>[...p,{id:Date.now(),text:t,done:false}]);
  const toggle=id=>setTasks(p=>p.map(x=>x.id===id?{...x,done:!x.done}:x));
  const remove=id=>setTasks(p=>p.filter(x=>x.id!==id));
  return { tasks, add, toggle, remove };
}
